const lead = $input.first().json;
const urgency = lead.urgency || '';
const name = [lead.firstName, lead.lastName].filter(Boolean).join(' ') || 'Unknown';
const service = lead.serviceNeeded || 'Service not specified';
const score = (lead.leadScore !== undefined && lead.leadScore !== '') ? lead.leadScore : '?';
const phone = lead.phone || 'No phone';
const leadId = lead.leadId || '';
const street = (lead.address || '').split(',')[0].trim();

// ⚠️ SETUP REQUIRED: Replace with the owner/rep E.164 phone number (e.g. '+16175550100')
const OWNER_PHONE = 'OWNER_PHONE_HERE';

const prefix = urgency === 'Emergency' ? '🚨 EMERGENCY' : '🔥 HOT LEAD';
let msg = prefix + ' (Score: ' + score + '/100)\n';
msg += name + ' — ' + service + '\n';
if (street) msg += street + '\n';
msg += 'Call: ' + phone;
if (leadId) msg += ' | ' + leadId;

return [{ json: { ...lead, ownerAlertMessage: msg, ownerPhone: OWNER_PHONE } }];
